I'm a self-taught dev running a tiny web shop. My API calls kept flaking, so I wrote this decorator. Feedback appreciated.
```python
import random, time
from functools import wraps
def retry(times=3, base=0.5, exceptions=(Exception,)):
    def deco(fn):
        @wraps(fn)
        def wrapper(*a, **kw):
            for i in range(times):
                try:
                    return fn(*a, **kw)
                except exceptions:
                    if i == times - 1:
                        raise
                    time.sleep(base * 2**i * random.uniform(0.5, 1.5))
        return wrapper
    return deco
```

